# Resolve the folder holding THIS agent's config.json. Use sys.executable ONLY
# when this module is the bundled standalone agent (its file lives inside the
# frozen bundle, sys._MEIPASS) — then config.json sits next to the exe. Otherwise
# use the module's own dir: covers a plain source run AND a loose agent.py imported
# into a FROZEN host (e.g. the compiled designer's in-process Debug Run, where
# sys.executable is the DESIGNER, not this agent — using it would load the wrong
# config.json and KeyError on 'llms').
_here = os.path.dirname(os.path.abspath(__file__))
_meipass = getattr(sys, "_MEIPASS", None)
if (getattr(sys, "frozen", False) and _meipass
        and os.path.abspath(_here).startswith(os.path.abspath(_meipass))):
    BASE_DIR = os.path.dirname(os.path.abspath(sys.executable))
else:
    BASE_DIR = _here

with open(os.path.join(BASE_DIR, "config.json"), encoding="utf-8") as _f:
    CONFIG = json.load(_f)

# ── where MUTABLE state lives ───────────────────────────────────────────────
# Everything this agent LEARNS — user accounts, ingested knowledge, memories,
# conversations, checkpoints — resolves against STATE_DIR. Everything it SHIPS
# WITH (config.json, skills, the RAG docs folder) and everything it can REBUILD
# (embedding/context caches) stays under BASE_DIR.
#
# They are the same directory by default, so a single-process agent is unchanged.
# Separating them is what lets SEVERAL REPLICAS behind a load balancer share one
# set of stores: mount one volume at this path in every replica. Caches stay
# per-replica on purpose — they are derived data, and concurrent whole-file
# rewrites of a shared cache would lose entries for no benefit.
#
# The environment wins over config.json so an operator can move it per deployment
# without editing the graph — the same rule as a remote_worker's base_url.
STATE_DIR = (os.environ.get("MTA_STATE_DIR", "").strip()
             or str((CONFIG.get("storage") or {}).get("state_dir", "") or "").strip()
             or BASE_DIR)
if not os.path.isabs(STATE_DIR):
    STATE_DIR = os.path.join(BASE_DIR, STATE_DIR)
if STATE_DIR != BASE_DIR:
    try:
        os.makedirs(STATE_DIR, exist_ok=True)
    except OSError as _e:                   # unwritable path: say so, don't die
        print("[state] cannot use %s (%s) — falling back to %s"
              % (STATE_DIR, _e, BASE_DIR), file=sys.stderr)
        STATE_DIR = BASE_DIR


def _env_secret(var: str) -> str:
    """The value of `var`, preferring the FILE named by `<var>_FILE`.

    The `_FILE` indirection is the docker/k8s convention (postgres and friends use it):
    the secret is mounted as a file, so it never enters the process environment and
    cannot leak through `docker inspect`, /proc/<pid>/environ, a child process that
    inherits it, or a library that logs os.environ. That last one matters more here
    than in most programs — this agent RUNS TOOLS, and a prompt-injected model with a
    code-execution tool can read its own environment.

    Falls back to the plain variable, so every existing deployment keeps working.
    """
    path = os.environ.get(var + "_FILE", "")
    if not path:
        return os.environ.get(var, "")
    try:
        with open(path, encoding="utf-8") as _f:
            return _f.read().strip()
    except OSError as _e:
        # Never fall back to the env var here: the operator asked for a FILE, and
        # silently using a stale/other value would hide a broken secret mount.
        print("[warn] %s_FILE=%s could not be read (%s) — treating as unset."
              % (var, path, _e), file=sys.stderr)
        return ""


def _env_slug(n) -> str:
    """A name as an ENV VAR fragment: siliconflow -> SILICONFLOW, My Bot -> MY_BOT."""
    return re.sub(r"[^A-Za-z0-9]+", "_", str(n)).upper().strip("_")


# Providers that legitimately need no key (local inference), so an empty api_key is
# normal there and must not produce a warning on every call.
_KEYLESS_PROVIDERS = {"ollama"}
_KEY_WARNED = set()


def _key_warn(agent_name: str, cfg: dict) -> None:
    """Warn ONCE per (agent, provider) when an LLM is about to be called with no key.

    Deliberately at CALL time rather than at import: the canvas injects a debug key
    into an already-imported module, so an import-time check would cry wolf on every
    Debug Run. Here the warning only fires when a real call is really about to fail,
    and it names the exact variable to set instead of leaving the user with a 401.
    """
    if cfg.get("api_key") or str(cfg.get("provider") or "") in _KEYLESS_PROVIDERS:
        return
    prov = str(cfg.get("provider") or "?")
    if (agent_name, prov) in _KEY_WARNED:
        return
    _KEY_WARNED.add((agent_name, prov))
    print("[warn] agent '%s' is calling provider '%s' with NO API key. Set %s_API_KEY "
          "(or AGENT_API_KEY) in the environment, or fill llms.%s[].api_key in "
          "config.json. The call will most likely fail with 401."
          % (agent_name, prov, _env_slug(prov), agent_name), file=sys.stderr)


def _env_overrides(cfg: dict) -> dict:
    """Let the ENVIRONMENT override config.json where a deployment needs it.

    config.json is the shipped default; a container platform supplies the parts that
    differ per environment. Without this, a Kubernetes Secret cannot reach the agent
    at all — the API key is only readable from the file, so the file would have to
    contain the secret, which is exactly what a Secret exists to avoid.

    Recognised (all OPT-IN — an unset variable changes nothing, so a plain run is
    byte-identical to before):

      AGENT_API_KEY              fills every BLANK llm api_key
      AGENT_API_KEY_<AGENT>      that agent's llm keys (name upper-cased, non
                                 alphanumerics -> _), and it WINS over a file value
      <PROVIDER>_API_KEY         e.g. SILICONFLOW_API_KEY / OPENAI_API_KEY — every
                                 llm spec on that provider, and it WINS over the
                                 file. Unlike AGENT_API_KEY this one is unambiguous
                                 about WHICH provider it belongs to, so overriding
                                 (not just blank-filling) is safe.
      REMOTE_<WORKER>_URL        overrides remote_workers.<worker>.base_url
      REMOTE_<WORKER>_TOKEN      bearer for that worker (see _remote_call)
      SERVER_HOST / SERVER_PORT / SERVER_REST_PORT / SERVER_TOKEN
      AGENT_METRICS              1/true -> collect metrics and serve /metrics
      AGENT_LOG_FORMAT           json -> one JSON object per line on stdout
      AGENT_LOG_PAYLOADS         1/true -> keep prompts/results in those log lines
      AGENT_SERVICE_NAME         the `service` label on metrics and log lines

    The four observability vars exist as ENV (not only as a graph setting) because
    they are a property of the DEPLOYMENT, not of the design: the same image runs
    in a laptop container with plain text logs and in a cluster with JSON logs and
    a Prometheus scrape, and rebuilding the agent to change that would be absurd.

    AGENT_API_KEY only fills BLANKS on purpose: a multi-LLM graph legitimately holds
    several providers' keys, and one env var must not flatten them all.
    """
    _slug = _env_slug
    _shared = _env_secret("AGENT_API_KEY")
    for _agent, _specs in (cfg.get("llms") or {}).items():
        _own = _env_secret("AGENT_API_KEY_" + _slug(_agent))
        for _sp in _specs:
            # Most specific wins: this agent > this provider > the file > a shared
            # key filling a blank. So `SILICONFLOW_API_KEY=...` in the environment
            # replaces whatever the designer left in config.json, while a graph that
            # mixes providers keeps each one's own key.
            _prov = (_env_secret(_slug(_sp.get("provider")) + "_API_KEY")
                     if _sp.get("provider") else "")
            if _own:
                _sp["api_key"] = _own          # explicit per-agent wins outright
            elif _prov:
                _sp["api_key"] = _prov         # provider-specific also wins outright
            elif _shared and not _sp.get("api_key"):
                _sp["api_key"] = _shared       # shared key only fills a blank
    for _name, _spec in (cfg.get("remote_workers") or {}).items():
        _u = os.environ.get("REMOTE_%s_URL" % _slug(_name), "")
        if _u:
            _spec["base_url"] = _u.rstrip("/")
    _srv = cfg.get("server")
    if isinstance(_srv, dict):
        for _k, _env, _cast in (("host", "SERVER_HOST", str),
                                ("port", "SERVER_PORT", int),
                                ("rest_port", "SERVER_REST_PORT", int),
                                ("auth_token", "SERVER_TOKEN", str)):
            _v = os.environ.get(_env)
            if _v not in (None, ""):
                try:
                    _srv[_k] = _cast(_v)
                except (TypeError, ValueError):
                    pass                       # a malformed override is ignored, not fatal
    # Observability (see the docstring): deployment-time switches, so ENV wins over
    # config.json outright rather than only filling a blank.
    _truthy = ("1", "true", "yes", "on")
    for _key, _env in (("metrics", "AGENT_METRICS"),
                       ("log_payloads", "AGENT_LOG_PAYLOADS")):
        _v = os.environ.get(_env)
        if _v not in (None, ""):
            cfg[_key] = _v.strip().lower() in _truthy
    for _key, _env in (("log_format", "AGENT_LOG_FORMAT"),
                       ("service_name", "AGENT_SERVICE_NAME")):
        _v = os.environ.get(_env)
        if _v not in (None, ""):
            cfg[_key] = _v.strip()
    return cfg


